using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Constructor_WithItems_SetsPageIndexAndTotalPages()
    {
        // Arrange
        var items = new List<string> { "a", "b", "c" };

        // Act
        var list = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(2, list.PageIndex);
        Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        Assert.Equal(3, list.Count);
        Assert.Equal("a", list[0]);
        Assert.Equal("b", list[1]);
        Assert.Equal("c", list[2]);
    }

    [Fact]
    public void Constructor_WithEmptyItems_SetsCountToZero()
    {
        var list = new PaginatedList<int>(new List<int>(), 0, 1, 10);

        Assert.Empty(list);
        Assert.Equal(1, list.PageIndex);
        Assert.Equal(0, list.TotalPages);
    }

    [Fact]
    public void TotalPages_ExactDivision_CalculatesCorrectly()
    {
        // 20 items, page size 5 = exactly 4 pages
        var list = new PaginatedList<int>(new List<int> { 1 }, 20, 1, 5);
        Assert.Equal(4, list.TotalPages);
    }

    [Fact]
    public void TotalPages_NotExactDivision_RoundsUp()
    {
        // 21 items, page size 5 = 5 pages (ceil)
        var list = new PaginatedList<int>(new List<int> { 1 }, 21, 1, 5);
        Assert.Equal(5, list.TotalPages);
    }

    [Fact]
    public void HasPreviousPage_OnFirstPage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);
        Assert.False(list.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_OnSecondPage_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);
        Assert.True(list.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);
        Assert.False(list.HasNextPage);
    }

    [Fact]
    public void HasNextPage_NotOnLastPage_ReturnsTrue()
    {
        var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);
        Assert.True(list.HasNextPage);
    }

    [Fact]
    public void Create_FromQueryable_ReturnsCorrectPage()
    {
        // Arrange
        var source = Enumerable.Range(1, 25).AsQueryable();

        // Act
        var page = PaginatedList<int>.Create(source, 2, 10);

        // Assert
        Assert.Equal(2, page.PageIndex);
        Assert.Equal(3, page.TotalPages); // ceil(25/10) = 3
        Assert.Equal(10, page.Count); // 10 items on page 2
        Assert.Equal(11, page[0]); // first item on page 2
        Assert.Equal(20, page[9]); // last item on page 2
        Assert.True(page.HasPreviousPage);
        Assert.True(page.HasNextPage);
    }

    [Fact]
    public void Create_FirstPage_ReturnsFirstItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(source, 1, 10);

        Assert.Equal(1, page.PageIndex);
        Assert.Equal(1, page[0]);
        Assert.Equal(10, page[9]);
        Assert.False(page.HasPreviousPage);
        Assert.True(page.HasNextPage);
    }

    [Fact]
    public void Create_LastPage_ReturnsRemainingItems()
    {
        var source = Enumerable.Range(1, 25).AsQueryable();

        var page = PaginatedList<int>.Create(source, 3, 10);

        Assert.Equal(3, page.PageIndex);
        Assert.Equal(5, page.Count); // only 5 remaining items
        Assert.Equal(21, page[0]);
        Assert.Equal(25, page[4]);
        Assert.True(page.HasPreviousPage);
        Assert.False(page.HasNextPage);
    }

    [Theory]
    [InlineData(1, 5, 1)]  // 1 item, page size 5 → 1 page
    [InlineData(5, 5, 1)]  // 5 items, page size 5 → 1 page
    [InlineData(6, 5, 2)]  // 6 items, page size 5 → 2 pages
    [InlineData(100, 10, 10)]
    public void Create_VariousCounts_CalculatesTotalPagesCorrectly(int totalItems, int pageSize, int expectedTotalPages)
    {
        var source = Enumerable.Range(1, totalItems).AsQueryable();

        var page = PaginatedList<int>.Create(source, 1, pageSize);

        Assert.Equal(expectedTotalPages, page.TotalPages);
    }
}

