public class HomeControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly HomeController _controller;

    public HomeControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new HomeController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Contact_ReturnsViewWithMessage()
    {
        var result = _controller.Contact() as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("Your contact page.", _controller.ViewBag.Message);
    }

    [Fact]
    public void Error_ReturnsViewResult()
    {
        var result = _controller.Error();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Unauthorized_ReturnsViewWithMessage()
    {
        var result = _controller.Unauthorized() as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
    }

    [Fact]
    public void About_WithNoStudents_ReturnsEmptyList()
    {
        var result = _controller.About() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<List<EnrollmentDateGroup>>(result.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void About_WithStudents_ReturnsGroupedEnrollmentDates()
    {
        // Arrange
        var date1 = DateTime.Parse("2010-09-01");
        var date2 = DateTime.Parse("2012-09-01");
        _context.Students.AddRange(
            new Student { FirstMidName = "A", LastName = "One", EnrollmentDate = date1 },
            new Student { FirstMidName = "B", LastName = "Two", EnrollmentDate = date1 },
            new Student { FirstMidName = "C", LastName = "Three", EnrollmentDate = date2 }
        );
        _context.SaveChanges();

        // Act
        var result = _controller.About() as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsType<List<EnrollmentDateGroup>>(result.Model);
        Assert.Equal(2, model.Count);
        var group2010 = model.Single(g => g.EnrollmentDate == date1);
        Assert.Equal(2, group2010.StudentCount);
        var group2012 = model.Single(g => g.EnrollmentDate == date2);
        Assert.Equal(1, group2012.StudentCount);
    }
}

