namespace ContosoUniversity.Tests;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new StudentsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
        _controller.TempData = new TempDataDictionary(
            _controller.ControllerContext.HttpContext,
            new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // -------- Index --------

    [Fact]
    public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
    {
        // Arrange
        _context.Students.AddRange(
            new Student { FirstMidName = "B", LastName = "Zorro", EnrollmentDate = DateTime.Today },
            new Student { FirstMidName = "A", LastName = "Alpha", EnrollmentDate = DateTime.Today }
        );
        _context.SaveChanges();

        // Act
        var result = _controller.Index(null, null, null, null) as ViewResult;

        // Assert
        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
        Assert.Equal(2, model.Count);
        Assert.Equal("Alpha", model[0].LastName);
        Assert.Equal("Zorro", model[1].LastName);
    }

    [Fact]
    public void Index_SortByNameDesc_ReturnsDescendingOrder()
    {
        _context.Students.AddRange(
            new Student { FirstMidName = "A", LastName = "Alpha", EnrollmentDate = DateTime.Today },
            new Student { FirstMidName = "B", LastName = "Zorro", EnrollmentDate = DateTime.Today }
        );
        _context.SaveChanges();

        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal("Zorro", model[0].LastName);
        Assert.Equal("Alpha", model[1].LastName);
    }

