using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class DepartmentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly DepartmentsController _controller;

    public DepartmentsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new DepartmentsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // -------- Index --------

    [Fact]
    public void Index_ReturnsViewWithDepartments()
    {
        _context.Departments.Add(new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 100000m,
            StartDate = DateTime.Today
        });
        _context.SaveChanges();

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Engineering", model[0].Name);
    }

    [Fact]
    public void Index_NoDepartments_ReturnsEmptyList()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(result.Model);
        Assert.Empty(model);
    }

    // -------- Details --------

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        var result = _controller.Details(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithDepartment()
    {
        var dept = new Department { DepartmentID = 10, Name = "Math", Budget = 50000m, StartDate = DateTime.Today };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var result = _controller.Details(10) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("Math", model.Name);
        Assert.Equal(50000m, model.Budget);
    }

    // -------- Create (GET) --------

    [Fact]
    public void Create_Get_ReturnsViewWithInstructorSelectList()
    {
        TestHelpers.SeedInstructors(_context);

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.InstructorID);
    }

    // -------- Create (POST) --------

    [Fact]
    public void Create_Post_ValidDepartment_RedirectsToIndex()
    {
        TestHelpers.SeedInstructors(_context);
        var dept = new Department
        {
            Name = "Physics",
            Budget = 200000m,
            StartDate = DateTime.Parse("2020-01-01"),
            InstructorID = 10
        };

        var result = _controller.Create(dept);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidDepartment_SavesToDB()
    {
        TestHelpers.SeedInstructors(_context);
        var dept = new Department
        {
            Name = "Physics",
            Budget = 200000m,
            StartDate = DateTime.Parse("2020-01-01"),
            InstructorID = 10
        };

        _controller.Create(dept);

        var saved = _context.Departments.Single(d => d.Name == "Physics");
        Assert.Equal(200000m, saved.Budget);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        TestHelpers.SeedInstructors(_context);
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department { Name = "", Budget = 0, StartDate = DateTime.Today };

        var result = _controller.Create(dept) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(dept, result.Model);
    }

    // -------- Edit (GET) --------

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_NotFound_ReturnsNotFound()
    {
        var result = _controller.Edit(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithDepartment()
    {
        TestHelpers.SeedDepartments(_context);

        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("English", model.Name);
    }

    // -------- Edit (POST) --------

    [Fact]
    public void Edit_Post_ValidDepartment_RedirectsToIndex()
    {
        TestHelpers.SeedDepartments(_context);
        var dept = _context.Departments.Find(1)!;
        _context.Entry(dept).State = EntityState.Detached;

        var editedDept = new Department
        {
            DepartmentID = 1,
            Name = "English Updated",
            Budget = 400000m,
            StartDate = dept.StartDate,
            InstructorID = dept.InstructorID
        };

        var result = _controller.Edit(editedDept);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        TestHelpers.SeedDepartments(_context);
        _controller.ModelState.AddModelError("Name", "Required");
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "",
            Budget = 0,
            StartDate = DateTime.Today
        };

        var result = _controller.Edit(dept) as ViewResult;

        Assert.NotNull(result);
    }

    // -------- Delete (GET) --------

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_NotFound_ReturnsNotFound()
    {
        var result = _controller.Delete(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithDepartment()
    {
        TestHelpers.SeedDepartments(_context);

        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Department>(result.Model);
        Assert.Equal("English", model.Name);
    }

    // -------- DeleteConfirmed (POST) --------

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
    {
        TestHelpers.SeedDepartments(_context);
        var initialCount = _context.Departments.Count();

        var result = _controller.DeleteConfirmed(1);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Departments.Count());
    }
}

