using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _envMock;
    private readonly Mock<ILogger<CoursesController>> _loggerMock;

    public CoursesControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _envMock = new Mock<IWebHostEnvironment>();
        _envMock.Setup(e => e.WebRootPath).Returns((string?)null);
        _envMock.Setup(e => e.ContentRootPath).Returns(System.IO.Path.GetTempPath());
        _loggerMock = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _envMock.Object, _loggerMock.Object);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // -------- Index --------

    [Fact]
    public void Index_ReturnsCoursesList()
    {
        TestHelpers.SeedCourses(_context);

        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Index_NoCourses_ReturnsEmptyList()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Empty(model);
    }

    // -------- Details --------

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithCourse()
    {
        TestHelpers.SeedCourses(_context);

        var result = _controller.Details(1050) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", model.Title);
        Assert.Equal(3, model.Credits);
    }

    // -------- Create (GET) --------

    [Fact]
    public void Create_Get_ReturnsViewWithSelectList()
    {
        TestHelpers.SeedDepartments(_context);

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal(0, model.CourseID); // new empty course
    }

    // -------- Create (POST) --------

    [Fact]
    public void Create_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        TestHelpers.SeedDepartments(_context);
        var course = new Course
        {
            CourseID = 5000,
            Title = "New Course",
            Credits = 4,
            DepartmentID = 1
        };

        var result = _controller.Create(course, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidCourse_SavesToDB()
    {
        TestHelpers.SeedDepartments(_context);
        var course = new Course
        {
            CourseID = 5000,
            Title = "New Course",
            Credits = 4,
            DepartmentID = 1
        };

        _controller.Create(course, null!);

        var saved = _context.Courses.Find(5000);
        Assert.NotNull(saved);
        Assert.Equal("New Course", saved.Title);
        Assert.Equal(4, saved.Credits);
        Assert.Equal(1, saved.DepartmentID);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        TestHelpers.SeedDepartments(_context);
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 5000, Title = "", Credits = 4, DepartmentID = 1 };

        var result = _controller.Create(course, null!) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal(course, result.Model);
    }

    [Fact]
    public void Create_Post_InvalidImageExtension_AddsModelError()
    {
        TestHelpers.SeedDepartments(_context);
        var course = new Course { CourseID = 5000, Title = "X", Credits = 3, DepartmentID = 1 };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(100);
        fileMock.Setup(f => f.FileName).Returns("file.exe");

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains(errors, e => e.ErrorMessage.Contains("valid image file"));
    }

    [Fact]
    public void Create_Post_FileTooBig_AddsModelError()
    {
        TestHelpers.SeedDepartments(_context);
        var course = new Course { CourseID = 5000, Title = "X", Credits = 3, DepartmentID = 1 };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit
        fileMock.Setup(f => f.FileName).Returns("photo.jpg");

        var result = _controller.Create(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
    }

    // -------- Edit (GET) --------

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null, null!);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_NotFound_ReturnsNotFound()
    {
        var result = _controller.Edit(999, null!);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCourse()
    {
        TestHelpers.SeedCourses(_context);

        var result = _controller.Edit(1050, null!) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    // -------- Edit (POST) --------

    [Fact]
    public void Edit_Post_ValidCourse_NoFile_RedirectsToIndex()
    {
        TestHelpers.SeedCourses(_context);
        var course = _context.Courses.Find(1050)!;
        _context.Entry(course).State = EntityState.Detached;

        var editedCourse = new Course
        {
            CourseID = 1050,
            Title = "Updated Chemistry",
            Credits = 3,
            DepartmentID = 1
        };

        var result = _controller.Edit(editedCourse, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidImageExtension_AddsModelError()
    {
        TestHelpers.SeedCourses(_context);
        var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(100);
        fileMock.Setup(f => f.FileName).Returns("file.txt");

        var result = _controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_FileTooBig_AddsModelError()
    {
        TestHelpers.SeedCourses(_context);
        var course = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 };
        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(6 * 1024 * 1024);
        fileMock.Setup(f => f.FileName).Returns("image.png");

        var result = _controller.Edit(course, fileMock.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        TestHelpers.SeedCourses(_context);
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 1050, Title = "", Credits = 3, DepartmentID = 1 };

        var result = _controller.Edit(course, null!) as ViewResult;

        Assert.NotNull(result);
    }

    // -------- Delete (GET) --------

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        TestHelpers.SeedCourses(_context);

        var result = _controller.Delete(1050) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", model.Title);
    }

    // -------- DeleteConfirmed (POST) --------

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
    {
        TestHelpers.SeedCourses(_context);
        var initialCount = _context.Courses.Count();

        var result = _controller.DeleteConfirmed(1050);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Courses.Count());
        Assert.Null(_context.Courses.Find(1050));
    }
}

