using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new InstructorsController(_context);
        _controller.ControllerContext = new ControllerContext
        {
            HttpContext = new DefaultHttpContext()
        };
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private void SeedInstructorsWithCourses()
    {
        var dept = new Department { DepartmentID = 1, Name = "English", Budget = 100000m, StartDate = DateTime.Today };
        _context.Departments.Add(dept);

        var course1 = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>() };
        var course2 = new Course { CourseID = 4022, Title = "Micro", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>() };
        _context.Courses.AddRange(course1, course2);

        var instructor = new Instructor
        {
            ID = 10,
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Parse("1995-03-11"),
            CourseAssignments = new List<CourseAssignment>
            {
                new CourseAssignment { CourseID = 1050, InstructorID = 10 }
            }
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
    }

    // -------- Index --------

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructors()
    {
        SeedInstructorsWithCourses();

        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Single(model.Instructors);
        Assert.Equal("Abercrombie", model.Instructors.First().LastName);
    }

    [Fact]
    public void Index_WithInstructorId_ShowsCourses()
    {
        SeedInstructorsWithCourses();

        var result = _controller.Index(10, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Chemistry", model.Courses.First().Title);
    }

    [Fact]
    public void Index_WithCourseId_ShowsEnrollments()
    {
        SeedInstructorsWithCourses();
        // Add enrollment for the course
        _context.Students.Add(new Student { ID = 1, FirstMidName = "Test", LastName = "User", EnrollmentDate = DateTime.Today });
        _context.SaveChanges();
        _context.Enrollments.Add(new Enrollment { StudentID = 1, CourseID = 1050, Grade = Grade.A });
        _context.SaveChanges();

        var result = _controller.Index(10, 1050) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    // -------- Details --------

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_ReturnsNotFound()
    {
        var result = _controller.Details(999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        SeedInstructorsWithCourses();

        var result = _controller.Details(10) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal("Abercrombie", model.LastName);
        Assert.Equal("Kim", model.FirstMidName);
    }

    // -------- Create (GET) --------

    [Fact]
    public void Create_Get_ReturnsViewWithInstructor()
    {
        SeedInstructorsWithCourses();

        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);
    }

    // -------- Create (POST) --------

    [Fact]
    public void Create_Post_ValidInstructor_NoSelectedCourses_RedirectsToIndex()
    {
        SeedInstructorsWithCourses();
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = DateTime.Parse("2020-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidInstructor_SavesToDB()
    {
        SeedInstructorsWithCourses();
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = DateTime.Parse("2020-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };

        _controller.Create(instructor, null!);

        var saved = _context.Instructors.Single(i => i.LastName == "Instructor");
        Assert.Equal("New", saved.FirstMidName);
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
    {
        SeedInstructorsWithCourses();
        var instructor = new Instructor
        {
            FirstMidName = "Jane",
            LastName = "Doe",
            HireDate = DateTime.Parse("2020-01-01"),
            CourseAssignments = new List<CourseAssignment>()
        };

        _controller.Create(instructor, new[] { "1050", "4022" });

        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .Single(i => i.LastName == "Doe");
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        SeedInstructorsWithCourses();
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "",
            HireDate = DateTime.Today,
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!) as ViewResult;

        Assert.NotNull(result);
    }

    // -------- Edit (GET) --------

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        SeedInstructorsWithCourses();
        // Also add office assignment
        _context.OfficeAssignments.Add(new OfficeAssignment { InstructorID = 10, Location = "Room 101" });
        _context.SaveChanges();

        var result = _controller.Edit(10) as ViewResult;

