using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class DbInitializerTests : IDisposable
{
    private readonly SchoolContext _context;

    public DbInitializerTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsStudents()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(8, _context.Students.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsInstructors()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(5, _context.Instructors.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsDepartments()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(4, _context.Departments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourses()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(7, _context.Courses.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsEnrollments()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(11, _context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(3, _context.OfficeAssignments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourseAssignments()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(8, _context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_AlreadySeeded_DoesNotDuplicateData()
    {
        // Seed once
        DbInitializer.Initialize(_context);
        var studentCountBefore = _context.Students.Count();
        var courseCountBefore = _context.Courses.Count();

        // Seed again
        DbInitializer.Initialize(_context);

        Assert.Equal(studentCountBefore, _context.Students.Count());
        Assert.Equal(courseCountBefore, _context.Courses.Count());
    }

    [Fact]
    public void Initialize_SeedsSpecificStudentNames()
    {
        DbInitializer.Initialize(_context);

        Assert.True(_context.Students.Any(s => s.LastName == "Alexander"));
        Assert.True(_context.Students.Any(s => s.LastName == "Alonso"));
        Assert.True(_context.Students.Any(s => s.LastName == "Olivetto"));
    }

    [Fact]
    public void Initialize_SeedsCorrectCourseCredits()
    {
        DbInitializer.Initialize(_context);

        var chemistry = _context.Courses.Single(c => c.Title == "Chemistry");
        Assert.Equal(3, chemistry.Credits);

        var calculus = _context.Courses.Single(c => c.Title == "Calculus");
        Assert.Equal(4, calculus.Credits);
    }

    [Fact]
    public void Initialize_SeedsCorrectDepartmentBudgets()
    {
        DbInitializer.Initialize(_context);

        var english = _context.Departments.Single(d => d.Name == "English");
        Assert.Equal(350000m, english.Budget);

        var math = _context.Departments.Single(d => d.Name == "Mathematics");
        Assert.Equal(100000m, math.Budget);
    }

    [Fact]
    public void Initialize_SeedsCorrectOfficeLocations()
    {
        DbInitializer.Initialize(_context);

        var offices = _context.OfficeAssignments.ToList();
        Assert.Contains(offices, o => o.Location == "Smith 17");
        Assert.Contains(offices, o => o.Location == "Gowan 27");
        Assert.Contains(offices, o => o.Location == "Thompson 304");
    }

    [Fact]
    public void Initialize_SeedsEnrollmentGrades()
    {
        DbInitializer.Initialize(_context);

        var enrollment = _context.Enrollments
            .Single(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
        Assert.Equal(Grade.A, enrollment.Grade);
    }

    [Fact]
    public void Initialize_SeedsNullGradeForAnand()
    {
        DbInitializer.Initialize(_context);

        var enrollment = _context.Enrollments
            .Single(e => e.Student.LastName == "Anand" && e.Course.Title == "Chemistry");
        Assert.Null(enrollment.Grade);
    }
}

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestHelpers.CreateInMemoryContext();
    }

    public void Dispose()
    {
        _context.Dispose();
    }

    [Fact]
    public void Context_CanAddAndRetrieveStudent()
    {
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = DateTime.Parse("2020-01-01")
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        var retrieved = _context.Students.First();
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal("User", retrieved.LastName);
    }

    [Fact]
    public void Context_CanAddAndRetrieveCourse()
    {
        _context.Departments.Add(new Department { DepartmentID = 1, Name = "Test", Budget = 100m, StartDate = DateTime.Today });
        _context.SaveChanges();

        var course = new Course { CourseID = 100, Title = "TestCourse", Credits = 3, DepartmentID = 1 };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var retrieved = _context.Courses.Find(100);
        Assert.NotNull(retrieved);
        Assert.Equal("TestCourse", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
    }

    [Fact]
    public void Context_CanAddAndRetrieveDepartment()
    {
        var dept = new Department { DepartmentID = 5, Name = "Science", Budget = 250000m, StartDate = DateTime.Today };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var retrieved = _context.Departments.Find(5);
        Assert.NotNull(retrieved);
        Assert.Equal("Science", retrieved.Name);
        Assert.Equal(250000m, retrieved.Budget);
    }

    [Fact]
    public void Context_CanAddAndRetrieveInstructor()
    {
        var instructor = new Instructor
        {
            FirstMidName = "Prof",
            LastName = "Smith",
            HireDate = DateTime.Parse("2000-01-01"),
            CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.First();
        Assert.Equal("Prof", retrieved.FirstMidName);
        Assert.Equal("Smith", retrieved.LastName);
    }

    [Fact]
    public void Context_CanAddNotification()
    {
        var notification = new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "New student",
            CreatedAt = DateTime.Now,
            CreatedBy = "System",
            IsRead = false
        };
        _context.Notifications.Add(notification);
        _context.SaveChanges();

        var retrieved = _context.Notifications.First();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("CREATE", retrieved.Operation);
        Assert.Equal("New student", retrieved.Message);
        Assert.False(retrieved.IsRead);
    }

    [Fact]
    public void Context_CourseAssignment_CompositeKey()
    {
        _context.Departments.Add(new Department { DepartmentID = 1, Name = "D", Budget = 100, StartDate = DateTime.Today });
        _context.SaveChanges();

        _context.Courses.Add(new Course { CourseID = 100, Title = "C", Credits = 3, DepartmentID = 1 });
        _context.Instructors.Add(new Instructor
        {
            ID = 50,
            FirstMidName = "A",
            LastName = "B",
            HireDate = DateTime.Today,
            CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
        });
        _context.SaveChanges();

        var ca = new CourseAssignment { CourseID = 100, InstructorID = 50 };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments.Find(100, 50);
        Assert.NotNull(retrieved);
        Assert.Equal(100, retrieved.CourseID);
        Assert.Equal(50, retrieved.InstructorID);
    }

    [Fact]
    public void Context_HasAllDbSets()
    {
        Assert.NotNull(_context.Courses);
        Assert.NotNull(_context.Enrollments);
        Assert.NotNull(_context.Departments);
        Assert.NotNull(_context.OfficeAssignments);
        Assert.NotNull(_context.CourseAssignments);
        Assert.NotNull(_context.People);
        Assert.NotNull(_context.Students);
        Assert.NotNull(_context.Instructors);
        Assert.NotNull(_context.Notifications);
    }
}

