[Fact]
public void TotalPages_RequiresCeiling()
{
    // Must verify ceiling is used, not floor
    var list = new PaginatedList<int>(new List<int>(), 11, 1, 5);
    Assert.Equal(3, list.TotalPages); // 11/5 = 2.2 → 3, not 2

