    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() => service.Dispose());
        Assert.Null(ex);
    }

    // --- Mutation-killing tests ---

    [Theory]
    [InlineData(EntityOperation.CREATE)]
    [InlineData(EntityOperation.UPDATE)]
    [InlineData(EntityOperation.DELETE)]
    public void SendNotification_AllOperations_CreatesUnreadNotification(EntityOperation op)
    {
        // Kills mutation: IsRead = false → IsRead = true
        _sut.SendNotification("Entity", "1", "Name", op);
        var notif = _sut.ReceiveNotification();

        Assert.NotNull(notif);
        Assert.False(notif.IsRead);
        Assert.Equal(op.ToString(), notif.Operation);
    }

    [Fact]
    public void SendNotification_CreateMessage_IncludesNewPrefix()
    {
        // Kills mutation: swapping CREATE/UPDATE/DELETE message templates
        _sut.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);
        var n = _sut.ReceiveNotification()!;
        Assert.StartsWith("New ", n.Message);
        Assert.Contains("has been created", n.Message);
    }

    [Fact]
    public void SendNotification_UpdateMessage_IncludesUpdatedSuffix()
    {
        _sut.SendNotification("Student", "1", "Alice", EntityOperation.UPDATE);
        var n = _sut.ReceiveNotification()!;
        Assert.DoesNotContain("New ", n.Message);
        Assert.Contains("has been updated", n.Message);
    }

    [Fact]
    public void SendNotification_DeleteMessage_IncludesDeletedSuffix()
    {
        _sut.SendNotification("Student", "1", "Alice", EntityOperation.DELETE);
        var n = _sut.ReceiveNotification()!;
        Assert.DoesNotContain("New ", n.Message);
        Assert.Contains("has been deleted", n.Message);
    }
}

