    [Fact]
    public void Index_SearchByFirstName_FindsMatch()
    {
        _context.Students.AddRange(
            new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Today },
            new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Today }
        );
        _context.SaveChanges();

        var result = _controller.Index(null, null, "Carson", null) as ViewResult;

        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Single(model);
        Assert.Equal("Carson", model[0].FirstMidName);
    }

    // --- Mutation-killing tests ---

    [Fact]
    public void Index_PaginatesAtExactlyTenPerPage()
    {
        // Kills mutation: pageSize = 10 → pageSize = 5/20/100
        for (int i = 0; i < 25; i++)
        {
            _context.Students.Add(new Student
            {
                FirstMidName = $"F{i:D2}",
                LastName = $"L{i:D2}",
                EnrollmentDate = DateTime.Today
            });
        }
        _context.SaveChanges();

        var result1 = _controller.Index(null, null, null, 1) as ViewResult;
        var page1 = Assert.IsAssignableFrom<PaginatedList<Student>>(result1!.Model);
        Assert.Equal(10, page1.Count);
        Assert.Equal(3, page1.TotalPages);

        var result3 = _controller.Index(null, null, null, 3) as ViewResult;
        var page3 = Assert.IsAssignableFrom<PaginatedList<Student>>(result3!.Model);
        Assert.Equal(5, page3.Count);
    }

    [Fact]
    public void Index_SearchString_ResetsToPageOne()
    {
        // Kills mutation: page = 1 → page = 2, or removing the reset
        for (int i = 0; i < 25; i++)
        {
            _context.Students.Add(new Student
            {
                FirstMidName = "Carson",
                LastName = $"A{i:D2}",
                EnrollmentDate = DateTime.Today
            });
        }
        _context.SaveChanges();

        var result = _controller.Index(null, null, "Carson", 5) as ViewResult;
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Create_Post_DateExactly1753Jan1_IsAccepted()
    {
        // Kills mutation: < new DateTime(1753,1,1) → <= new DateTime(1753,1,1)
        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "Boundary",
            EnrollmentDate = new DateTime(1753, 1, 1)
        };

        var result = _controller.Create(student);

        Assert.IsType<RedirectToActionResult>(result);
    }

